"use client";

import { use, useState } from "react";
import { ProjectSubNav } from "@/app/components/project-sub-nav";
import { ChevronLeft, ChevronRight } from "lucide-react";

export default function ProjectTimelinePage({ params }: { params: Promise<{ projectId: string }> }) {
  const { projectId } = use(params);
  const [zoom, setZoom] = useState<"Day" | "Week" | "Month">("Week");

  const timelineTasks = [
    { title: "Database Architecture", start: 5, duration: 25, color: "bg-emerald-500", assignee: "Quân Nguyễn" },
    { title: "Authentication & MFA", start: 20, duration: 35, color: "bg-blue-500", assignee: "Trường Hoàng" },
    { title: "Kanban Board Interactivity", start: 40, duration: 30, color: "bg-amber-500", assignee: "Lan Anh" },
    { title: "Analytics & Stripe Billing", start: 60, duration: 30, color: "bg-purple-500", assignee: "Minh Châu" },
  ];

  return (
    <div className="p-6">
      <ProjectSubNav projectId={projectId} projectName="Dự án SaaS TaskFlow" />

      {/* Controls */}
      <div className="flex flex-wrap items-center justify-between gap-4 mb-6">
        <div className="flex items-center gap-2">
          <button className="button secondary">
            <ChevronLeft size={16} /> Tháng trước
          </button>
          <span className="font-semibold text-sm text-[var(--ink)]">Tháng 9 - Tháng 10 / 2026</span>
          <button className="button secondary">
            Tháng sau <ChevronRight size={16} />
          </button>
        </div>

        <div className="flex items-center gap-1 rounded-lg border border-[var(--line)] bg-white p-1">
          {(["Day", "Week", "Month"] as const).map((mode) => (
            <button
              key={mode}
              onClick={() => setZoom(mode)}
              className={`rounded-md px-3 py-1 text-xs font-semibold transition-colors ${
                zoom === mode ? "bg-[var(--primary)] text-white" : "text-[var(--muted)] hover:text-[var(--ink)]"
              }`}
            >
              {mode}
            </button>
          ))}
        </div>
      </div>

      {/* Gantt Timeline Graphic */}
      <div className="overflow-x-auto rounded-xl border border-[var(--line)] bg-white p-6 shadow-sm">
        <div className="min-w-[800px]">
          {/* Timeline Header Months/Weeks */}
          <div className="flex border-b border-[var(--line)] pb-3 font-semibold text-xs text-[var(--muted)]">
            <div className="w-64">Tên công việc</div>
            <div className="flex-1 grid grid-cols-4 text-center">
              <span>Tuần 1</span>
              <span>Tuần 2</span>
              <span>Tuần 3</span>
              <span>Tuần 4</span>
            </div>
          </div>

          {/* Timeline Bars */}
          <div className="divide-y divide-[var(--line)]">
            {timelineTasks.map((t, idx) => (
              <div key={idx} className="flex items-center py-4 hover:bg-[#f8fbf8] transition-colors">
                <div className="w-64 pr-4">
                  <div className="font-semibold text-sm text-[var(--ink)]">{t.title}</div>
                  <div className="text-xs text-[var(--muted)]">{t.assignee}</div>
                </div>
                <div className="flex-1 relative h-8 bg-gray-50 rounded-lg overflow-hidden">
                  <div
                    className={`absolute top-1 bottom-1 rounded-md ${t.color} text-white flex items-center px-3 text-xs font-bold shadow-sm transition-all`}
                    style={{ left: `${t.start}%`, width: `${t.duration}%` }}
                  >
                    {t.title}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

/* eslint-disable jsx-a11y/click-events-have-key-events, jsx-a11y/no-static-element-interactions */
"use client";

import { use, useState } from "react";
import Link from "next/link";
import { ArrowLeft, CheckCircle2, RefreshCw, Unplug, Save } from "lucide-react";

export default function IntegrationDetailPage({ params }: { params: Promise<{ provider: string }> }) {
  const { provider } = use(params);
  const [channel, setChannel] = useState("#proj-taskflow-updates");
  const [testing, setTesting] = useState(false);
  const [testSuccess, setTestSuccess] = useState(false);

  const providerName = provider.toUpperCase();

  const handleTestConnection = () => {
    setTesting(true);
    setTimeout(() => {
      setTesting(false);
      setTestSuccess(true);
      setTimeout(() => setTestSuccess(false), 3000);
    }, 1200);
  };

  return (
    <div className="space-y-6 max-w-3xl">
      <Link href="/app/settings/integrations" className="text-xs font-semibold text-[var(--muted)] hover:underline flex items-center gap-1">
        <ArrowLeft size={14} /> Danh sách ứng dụng
      </Link>

      <div className="rounded-xl border border-[var(--line)] bg-white p-6 shadow-sm">
        <div className="flex items-center justify-between border-b border-[var(--line)] pb-4 mb-6">
          <div>
            <h1 className="text-xl font-bold text-[var(--ink)]">Cấu hình kết nối {providerName}</h1>
            <p className="text-xs text-[var(--muted)] mt-1">Trạng thái: Đã xác thực tài khoản tổ chức</p>
          </div>
          <span className="badge">Đang hoạt động</span>
        </div>

        {testSuccess && (
          <div className="mb-6 flex items-center gap-2 rounded-xl bg-emerald-50 p-4 text-xs font-semibold text-emerald-800">
            <CheckCircle2 size={16} /> Gửi tin nhắn thử nghiệm tới {providerName} thành công!
          </div>
        )}

        <div className="space-y-4">
          <div className="field">
            <label>Kênh nhận thông báo (Notification Channel / Webhook)</label>
            <input value={channel} onChange={(e) => setChannel(e.target.value)} />
          </div>

          <div className="flex items-center gap-3 pt-2">
            <button onClick={handleTestConnection} disabled={testing} className="button secondary text-xs">
              <RefreshCw size={14} className={testing ? "animate-spin" : ""} />
              {testing ? "Đang thử..." : "Gửi thử nghiệm"}
            </button>
            <button className="button primary text-xs">
              <Save size={14} /> Lưu cài đặt
            </button>
          </div>
        </div>

        <div className="mt-8 border-t border-[var(--line)] pt-6 flex justify-between items-center">
          <span className="text-xs text-[var(--muted)]">Hủy liên kết tài khoản {providerName} khỏi workspace</span>
          <button className="button danger text-xs">
            <Unplug size={14} /> Ngắt kết nối
          </button>
        </div>
      </div>
    </div>
  );
}

/* eslint-disable jsx-a11y/click-events-have-key-events, jsx-a11y/no-static-element-interactions */
"use client";

import React from "react";
import {
  Plus,
  Pencil,
  Trash2,
  ArrowRight,
  UserPlus,
  Paperclip,
  Clock,
  Folder,
  ChevronRight,
  ExternalLink,
} from "lucide-react";
import { ActivityLogItem, ActivityActionType } from "./types";

interface ActivityCardProps {
  item: ActivityLogItem;
  onSelectTask: (taskId: string) => void;
  isLastInGroup?: boolean;
}

// Action type icon & color map
const ACTION_CONFIG: Record<
  ActivityActionType,
  {
    icon: React.ElementType;
    badgeBg: string;
    badgeColor: string;
    borderColor: string;
    label: string;
  }
> = {
  create: {
    icon: Plus,
    badgeBg: "bg-emerald-500",
    badgeColor: "text-zinc-950",
    borderColor: "border-emerald-500/40",
    label: "Tạo mới",
  },
  update: {
    icon: Pencil,
    badgeBg: "bg-amber-500",
    badgeColor: "text-zinc-950",
    borderColor: "border-amber-500/40",
    label: "Chỉnh sửa",
  },
  move: {
    icon: ArrowRight,
    badgeBg: "bg-blue-500",
    badgeColor: "text-zinc-950",
    borderColor: "border-blue-500/40",
    label: "Đổi trạng thái",
  },
  assign: {
    icon: UserPlus,
    badgeBg: "bg-purple-500",
    badgeColor: "text-zinc-950",
    borderColor: "border-purple-500/40",
    label: "Gán người làm",
  },
  delete: {
    icon: Trash2,
    badgeBg: "bg-red-500",
    badgeColor: "text-zinc-950",
    borderColor: "border-red-500/40",
    label: "Đã xóa",
  },
  attachment: {
    icon: Paperclip,
    badgeBg: "bg-cyan-500",
    badgeColor: "text-zinc-950",
    borderColor: "border-cyan-500/40",
    label: "File đính kèm",
  },
};

export const ActivityCard: React.FC<ActivityCardProps> = ({
  item,
  onSelectTask,
  isLastInGroup = false,
}) => {
  const actionMeta = ACTION_CONFIG[item.actionType] || ACTION_CONFIG.update;
  const ActionIcon = actionMeta.icon;

  // Render Humanized text with highlighted clickable target
  const renderHumanizedDescription = () => {
    return (
      <div className="text-sm text-zinc-300 leading-relaxed">
        <span className="font-semibold text-zinc-100 hover:text-emerald-400 cursor-pointer">
          {item.actorName}
        </span>{" "}
        <span className="text-zinc-400 font-normal">{item.actionText}</span>{" "}
        {item.targetId ? (
          <button
            onClick={() => onSelectTask(item.targetId!)}
            className="inline-flex items-center gap-1 font-semibold text-emerald-400 hover:text-emerald-300 hover:underline bg-emerald-950/40 border border-emerald-800/40 rounded px-1.5 py-0.5 ml-1 transition-all"
          >
            {item.targetCode && (
              <span className="text-xs opacity-75 font-mono">[{item.targetCode}]</span>
            )}
            <span>{item.targetTitle}</span>
            <ExternalLink className="w-3 h-3 opacity-70" />
          </button>
        ) : (
          <span className="font-semibold text-zinc-200">&quot;{item.targetTitle}&quot;</span>
        )}
      </div>
    );
  };

  return (
    <div className="relative flex gap-4 group">
      {/* Left Column: Timeline Line & Actor Avatar Overlay */}
      <div className="flex flex-col items-center">
        <div className="relative">
          {/* Avatar */}
          <img
            src={item.actorAvatar}
            alt={item.actorName}
            className="w-10 h-10 rounded-full object-cover border-2 border-zinc-800 shadow-md group-hover:border-emerald-500/60 transition-colors"
          />
          {/* Icon Badge Overlay */}
          <div
            className={`absolute -bottom-1 -right-1 w-5 h-5 rounded-full ${actionMeta.badgeBg} ${actionMeta.badgeColor} flex items-center justify-center ring-2 ring-zinc-950 shadow-sm`}
            title={actionMeta.label}
          >
            <ActionIcon className="w-3 h-3 stroke-[2.5]" />
          </div>
        </div>

        {/* Vertical Connecting Line (Jira/GitHub audit log style) */}
        {!isLastInGroup && (
          <div className="w-0.5 flex-1 bg-gradient-to-b from-zinc-700/60 via-zinc-800 to-transparent my-2 group-hover:from-emerald-500/40 transition-colors"></div>
        )}
      </div>

      {/* Right Column: Main Activity Content Card */}
      <div className="flex-1 pb-6">
        <div className="bg-zinc-900/60 hover:bg-zinc-900 border border-zinc-800/80 group-hover:border-zinc-700/80 rounded-xl p-4 transition-all shadow-sm">
          {/* Header Row: Action humanized sentence & timestamp */}
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-2">
            {renderHumanizedDescription()}

            {/* Time badge */}
            <div className="flex items-center gap-1.5 text-xs text-zinc-400 shrink-0 bg-zinc-950/50 px-2.5 py-1 rounded-md border border-zinc-800/60">
              <Clock className="w-3 h-3 text-zinc-500" />
              <span>{item.exactTime}</span>
              <span className="text-zinc-600">•</span>
              <span className="text-zinc-400">{item.relativeTime}</span>
            </div>
          </div>

          {/* Scope / Project Badge Tag */}
          {item.projectName && (
            <div className="flex items-center gap-2 mb-3">
              <span className="inline-flex items-center gap-1.5 text-xs font-medium px-2 py-0.5 rounded-full bg-zinc-800/80 text-zinc-300 border border-zinc-700/50">
                <Folder className="w-3 h-3 text-amber-400" />
                <span>{item.projectName}</span>
              </span>
            </div>
          )}

          {/* Visual Diff Block (Old Value ➔ New Value) */}
          {item.diff && (
            <div className="mt-3 bg-zinc-950/80 border border-zinc-800/80 rounded-lg p-3 text-xs space-y-2">
              <div className="text-zinc-400 font-medium flex items-center gap-1.5">
                <span>Chi tiết thay đổi trường:</span>
                <span className="font-semibold text-zinc-200 bg-zinc-800 px-1.5 py-0.5 rounded text-[11px]">
                  {item.diff.fieldName}
                </span>
              </div>

              <div className="flex flex-col sm:flex-row sm:items-center gap-2 pt-1">
                {/* Old Value Box */}
                {item.diff.oldValue && (
                  <div className="flex-1 bg-red-950/30 border border-red-900/40 text-red-300 rounded px-2.5 py-1.5 font-mono line-through opacity-85 break-all">
                    <span className="text-[10px] text-red-400 uppercase tracking-wider block font-sans font-semibold mb-0.5">
                      Giá trị cũ
                    </span>
                    {item.diff.oldValue}
                  </div>
                )}

                {/* Arrow Icon */}
                <div className="self-center text-zinc-500 font-bold shrink-0">
                  <ChevronRight className="w-4 h-4 hidden sm:block text-zinc-400" />
                  <span className="sm:hidden text-xs">⬇</span>
                </div>

                {/* New Value Box */}
                <div className="flex-1 bg-emerald-950/40 border border-emerald-800/50 text-emerald-300 rounded px-2.5 py-1.5 font-mono font-medium break-all">
                  <span className="text-[10px] text-emerald-400 uppercase tracking-wider block font-sans font-semibold mb-0.5">
                    Giá trị mới
                  </span>
                  {item.diff.newValue}
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

/* eslint-disable jsx-a11y/click-events-have-key-events, jsx-a11y/no-static-element-interactions */
"use client";

import React from "react";
import {
  Calendar,
  Inbox,
  RotateCcw,
  CheckCircle2,
} from "lucide-react";
import { useWorkspace } from "../providers/workspace-provider";
import { useActivityLog } from "./useActivityLog";
import { ActivityToolbar } from "./ActivityToolbar";
import { ActivityCard } from "./ActivityCard";
import { TaskDetailDrawer } from "../tasks/TaskDetailDrawer";

export const ActivityDashboardContainer: React.FC = () => {
  const workspace = useWorkspace();
  const {
    groupedTimeline,
    totalCount,
    filters,
    setFilters,
    resetFilters,
    hasActiveFilters,
    exportCSV,
    selectedTaskId,
    setSelectedTaskId,
    closeDrawer,
    toast,
  } = useActivityLog();

  return (
    <div className="min-h-screen bg-zinc-950 text-zinc-100 p-4 md:p-8 relative">
      {/* Toast Notification */}
      {toast && (
        <div className="fixed bottom-6 right-6 z-50 flex items-center gap-3 px-4 py-3 rounded-xl bg-emerald-950 border border-emerald-700 text-emerald-200 shadow-2xl animate-in fade-in slide-in-from-bottom-4 duration-300">
          <CheckCircle2 className="w-5 h-5 text-emerald-400 shrink-0" />
          <span className="text-sm font-medium">{toast.message}</span>
        </div>
      )}

      {/* Main Container */}
      <div className="max-w-5xl mx-auto space-y-6">
        {/* Header & Filter Controls Toolbar */}
        <ActivityToolbar
          filters={filters}
          onFilterChange={setFilters}
          onResetFilters={resetFilters}
          hasActiveFilters={hasActiveFilters}
          totalCount={totalCount}
          onExportCSV={exportCSV}
        />

        {/* Grouped Timeline Feed */}
        {groupedTimeline.length > 0 ? (
          <div className="space-y-8">
            {groupedTimeline.map((group) => (
              <div key={group.groupKey} className="space-y-4">
                {/* Timeline Group Header */}
                <div className="sticky top-16 z-10 bg-zinc-950/90 backdrop-blur-md py-2 border-b border-zinc-800/80 flex items-center justify-between">
                  <div className="flex items-center gap-2.5">
                    <div className="p-1.5 rounded-lg bg-emerald-950/80 border border-emerald-800/60 text-emerald-400">
                      <Calendar className="w-4 h-4" />
                    </div>
                    <h2 className="text-base font-semibold text-zinc-100 tracking-tight">
                      {group.groupTitle}
                    </h2>
                    <span className="text-xs font-semibold px-2 py-0.5 rounded-full bg-zinc-900 border border-zinc-800 text-zinc-400">
                      {group.items.length} nhật ký
                    </span>
                  </div>
                </div>

                {/* Timeline Cards Stream */}
                <div className="pt-2 pl-2 sm:pl-4">
                  {group.items.map((item, idx) => (
                    <ActivityCard
                      key={item.id}
                      item={item}
                      onSelectTask={setSelectedTaskId}
                      isLastInGroup={idx === group.items.length - 1}
                    />
                  ))}
                </div>
              </div>
            ))}

            {/* Infinite Scroll / Bottom Indicator */}
            <div className="py-8 text-center border-t border-zinc-800/60">
              <div className="inline-flex items-center gap-2 text-xs text-zinc-500 bg-zinc-900/60 px-4 py-2 rounded-full border border-zinc-800">
                <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400" />
                <span>Đã hiển thị toàn bộ {totalCount} nhật ký kiểm toán phù hợp</span>
              </div>
            </div>
          </div>
        ) : (
          /* Empty State */
          <div className="bg-zinc-900/50 border border-zinc-800/80 rounded-2xl p-12 text-center my-8">
            <div className="w-16 h-16 rounded-full bg-zinc-800/60 border border-zinc-700/50 flex items-center justify-center mx-auto mb-4 text-zinc-400">
              <Inbox className="w-8 h-8 text-zinc-500" />
            </div>
            <h3 className="text-lg font-semibold text-zinc-200 mb-1">
              Không tìm thấy nhật ký hoạt động phù hợp
            </h3>
            <p className="text-sm text-zinc-400 max-w-md mx-auto mb-6">
              Không có bản ghi nào tương ứng với các tiêu chí tìm kiếm hoặc bộ lọc hiện tại của bạn.
            </p>
            {hasActiveFilters && (
              <button
                onClick={resetFilters}
                className="inline-flex items-center gap-2 px-4 py-2 rounded-lg bg-emerald-600 hover:bg-emerald-500 text-white font-medium text-sm transition-all shadow-md"
              >
                <RotateCcw className="w-4 h-4" />
                <span>Bỏ bộ lọc và xem tất cả</span>
              </button>
            )}
          </div>
        )}
      </div>

      {/* Slide-over Task Detail Drawer */}
      {selectedTaskId && (
        <TaskDetailDrawer
          workspaceId={workspace.id}
          taskId={selectedTaskId}
          isOpen={Boolean(selectedTaskId)}
          onClose={closeDrawer}
        />
      )}
    </div>
  );
};

/* eslint-disable jsx-a11y/click-events-have-key-events, jsx-a11y/no-static-element-interactions */
"use client";

import React from "react";
import {
  Search,
  X,
  Download,
  Filter,
  User,
  Activity,
  Folder,
  Calendar,
  RotateCcw,
  Sparkles,
  Wifi,
} from "lucide-react";
import { ActivityFilterState, ActivityActionType } from "./types";

interface ActivityToolbarProps {
  filters: ActivityFilterState;
  onFilterChange: (filters: ActivityFilterState) => void;
  onResetFilters: () => void;
  hasActiveFilters: boolean;
  totalCount: number;
  onExportCSV: () => void;
}

export const ActivityToolbar: React.FC<ActivityToolbarProps> = ({
  filters,
  onFilterChange,
  onResetFilters,
  hasActiveFilters,
  totalCount,
  onExportCSV,
}) => {
  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onFilterChange({ ...filters, searchQuery: e.target.value });
  };

  const handleClearSearch = () => {
    onFilterChange({ ...filters, searchQuery: "" });
  };

  return (
    <div className="space-y-4 mb-6">
      {/* Top Header Row */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <div className="flex items-center gap-3">
            <h1 className="text-2xl font-bold text-zinc-100 tracking-tight flex items-center gap-2">
              <Activity className="w-6 h-6 text-emerald-400" />
              Lịch sử hoạt động
            </h1>
            <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold bg-emerald-950/80 text-emerald-400 border border-emerald-800/50">
              {totalCount} nhật ký
            </span>
            <div className="hidden md:flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs bg-zinc-900 border border-zinc-800 text-zinc-400">
              <span className="relative flex h-2 w-2">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
                <span className="relative inline-flex rounded-full h-2 w-2 bg-emerald-500"></span>
              </span>
              <Wifi className="w-3 h-3 text-emerald-400" />
              <span>Realtime Stream Active</span>
            </div>
          </div>
          <p className="text-sm text-zinc-400 mt-1">
