          <button
            onClick={onGoToday}
            className="px-3.5 py-1.5 rounded-xl bg-zinc-950 hover:bg-zinc-800 border border-zinc-800 text-zinc-200 text-xs font-semibold transition-colors"
            title="Trở về Hôm nay (Phím T)"
