            Hôm nay
          </button>

          <button
            onClick={onGoNext}
            className="p-2 rounded-xl bg-zinc-950 hover:bg-zinc-800 border border-zinc-800 text-zinc-300 transition-colors"
            title="Trang tiếp (Phím mũi tên Phải)"
