          >
            <option value="none">Gom nhóm: Không</option>
            <option value="project">Gom nhóm: Theo Dự án</option>
            <option value="dueDate">Gom nhóm: Theo Hạn chót</option>
            <option value="status">Gom nhóm: Theo Trạng thái</option>
