"use client";

import React from "react";
import { X, Settings, Mail, Bell, Save } from "lucide-react";
import { NotificationSettings } from "./types";

interface NotificationSettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  settings: NotificationSettings;
  onSaveSettings: (newSettings: NotificationSettings) => void;
}

export function NotificationSettingsModal({
  isOpen,
  onClose,
  settings,
  onSaveSettings,
}: NotificationSettingsModalProps) {
  const [localSettings, setLocalSettings] = React.useState<NotificationSettings>(settings);

  React.useEffect(() => {
    const syncTimer = window.setTimeout(() => setLocalSettings(settings), 0);
    return () => window.clearTimeout(syncTimer);
  }, [settings]);

  if (!isOpen) return null;

  const handleToggle = (key: keyof NotificationSettings) => {
    setLocalSettings((prev) => ({ ...prev, [key]: !prev[key] }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSaveSettings(localSettings);
    onClose();
  };

  return (
    <>
      <button type="button" aria-label="Đóng cài đặt thông báo" className="fixed inset-0 z-50 bg-black/70 backdrop-blur-sm animate-fadeIn" onClick={onClose} />
      <div className="fixed top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-50 w-full max-w-lg p-6 rounded-2xl bg-zinc-950 border border-zinc-800 text-zinc-100 shadow-2xl space-y-5 animate-scaleUp">
        {/* Header */}
        <div className="flex items-center justify-between border-b border-zinc-800 pb-3">
          <div className="flex items-center gap-2">
            <div className="p-2 rounded-lg bg-emerald-500/10 text-emerald-400">
              <Settings className="w-5 h-5" />
            </div>
            <div>
              <h3 className="text-lg font-bold text-zinc-100">Cài đặt kênh Thông báo</h3>
              <p className="text-xs text-zinc-400">Tùy chỉnh nhận thông báo qua Email, Push & Sound</p>
            </div>
          </div>
          <button onClick={onClose} className="p-1 rounded-lg text-zinc-400 hover:text-white hover:bg-zinc-900">
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Form Toggles */}
        <form onSubmit={handleSubmit} className="space-y-5 text-xs sm:text-sm">
          {/* Email Notifications */}
          <div className="space-y-3 p-4 rounded-xl bg-zinc-900/60 border border-zinc-800">
            <div className="flex items-center gap-2 font-bold text-zinc-200">
              <Mail className="w-4 h-4 text-emerald-400" />
              <span>Thông báo qua Email</span>
            </div>

            <div className="space-y-2">
              <label className="flex items-center justify-between cursor-pointer">
                <span className="text-zinc-300 text-xs">Khi có ai đó nhắc đến bạn (@mention)</span>
                <input
                  type="checkbox"
                  checked={localSettings.emailMentions}
                  onChange={() => handleToggle("emailMentions")}
                  className="w-4 h-4 accent-emerald-500 rounded cursor-pointer"
                />
              </label>

              <label className="flex items-center justify-between cursor-pointer">
                <span className="text-zinc-300 text-xs">Cảnh báo công việc sắp hết hạn (Deadline)</span>
                <input
                  type="checkbox"
                  checked={localSettings.emailDeadlines}
                  onChange={() => handleToggle("emailDeadlines")}
                  className="w-4 h-4 accent-emerald-500 rounded cursor-pointer"
                />
              </label>

              <label className="flex items-center justify-between cursor-pointer">
                <span className="text-zinc-300 text-xs">Khi được giao công việc mới</span>
                <input
                  type="checkbox"
                  checked={localSettings.emailAssignments}
                  onChange={() => handleToggle("emailAssignments")}
                  className="w-4 h-4 accent-emerald-500 rounded cursor-pointer"
                />
              </label>
            </div>
          </div>

          {/* Browser Push Notifications */}
          <div className="space-y-3 p-4 rounded-xl bg-zinc-900/60 border border-zinc-800">
            <div className="flex items-center gap-2 font-bold text-zinc-200">
              <Bell className="w-4 h-4 text-blue-400" />
              <span>Thông báo đẩy Trình duyệt (Push Notifications)</span>
            </div>

            <div className="space-y-2">
              <label className="flex items-center justify-between cursor-pointer">
                <span className="text-zinc-300 text-xs">Thông báo đẩy khi có @mention</span>
                <input
                  type="checkbox"
                  checked={localSettings.pushMentions}
                  onChange={() => handleToggle("pushMentions")}
                  className="w-4 h-4 accent-emerald-500 rounded cursor-pointer"
                />
              </label>

              <label className="flex items-center justify-between cursor-pointer">
                <span className="text-zinc-300 text-xs">Thông báo đẩy khi công việc hết hạn</span>
                <input
                  type="checkbox"
                  checked={localSettings.pushDeadlines}
                  onChange={() => handleToggle("pushDeadlines")}
                  className="w-4 h-4 accent-emerald-500 rounded cursor-pointer"
                />
              </label>
            </div>
          </div>

          {/* Actions */}
          <div className="flex items-center justify-end gap-3 pt-2 border-t border-zinc-800">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 rounded-xl bg-zinc-900 hover:bg-zinc-800 text-zinc-300 font-medium text-xs transition-colors"
            >
              Hủy
            </button>
            <button
              type="submit"
              className="flex items-center gap-1.5 px-4 py-2 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white font-semibold text-xs shadow-md transition-colors"
            >
              <Save className="w-4 h-4" />
              <span>Lưu cài đặt</span>
            </button>
          </div>
        </form>
      </div>
    </>
  );
}

/* eslint-disable jsx-a11y/click-events-have-key-events, jsx-a11y/no-static-element-interactions */
"use client";

import React from "react";
import {
  Bell,
  CheckCheck,
  Settings,
  Search,
  X,
  Volume2,
  VolumeX,
  AtSign,
  UserCheck,
  ShieldAlert,
} from "lucide-react";
import { NotificationCategoryTab, CategoryTabCounts } from "./types";

interface NotificationToolbarProps {
  activeTab: NotificationCategoryTab;
  onTabChange: (tab: NotificationCategoryTab) => void;
  counts: CategoryTabCounts;
  searchQuery: string;
  onSearchChange: (query: string) => void;
  onClearSearch: () => void;
  onMarkAllAsRead: () => void;
  onOpenSettings: () => void;
  soundEnabled: boolean;
  onToggleSound: () => void;
}

export function NotificationToolbar({
  activeTab,
  onTabChange,
  counts,
  searchQuery,
  onSearchChange,
  onClearSearch,
  onMarkAllAsRead,
  onOpenSettings,
  soundEnabled,
  onToggleSound,
}: NotificationToolbarProps) {
  const tabs: { id: NotificationCategoryTab; label: string; icon: React.ElementType; count: number; isUnreadBadge?: boolean }[] = [
    { id: "all", label: "Tất cả", icon: Bell, count: counts.all },
    { id: "unread", label: "Chưa đọc", icon: Bell, count: counts.unread, isUnreadBadge: true },
    { id: "mention", label: "Nhắc đến", icon: AtSign, count: counts.mention },
    { id: "assignment", label: "Việc được giao", icon: UserCheck, count: counts.assignment },
    { id: "system", label: "Hệ thống", icon: ShieldAlert, count: counts.system },
  ];

  return (
    <div className="space-y-4">
      {/* Top Action Bar */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 p-3 rounded-2xl bg-zinc-900/90 border border-zinc-800">
        {/* Search Input */}
        <div className="relative flex-1 min-w-[200px]">
          <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-zinc-400 pointer-events-none" />
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => onSearchChange(e.target.value)}
            placeholder="Tìm kiếm thông báo theo từ khóa, người gửi..."
            className="w-full pl-9 pr-8 py-2 rounded-xl bg-zinc-950 border border-zinc-800 text-xs text-zinc-200 placeholder-zinc-500 focus:outline-none focus:border-emerald-500/60"
          />
          {searchQuery && (
            <button
              onClick={onClearSearch}
              className="absolute right-2.5 top-1/2 -translate-y-1/2 text-zinc-400 hover:text-zinc-200"
            >
              <X className="w-3.5 h-3.5" />
            </button>
          )}
        </div>

        {/* Action Controls Right */}
        <div className="flex items-center gap-2 flex-wrap">
          {/* Sound Toggle Button */}
          <button
            onClick={onToggleSound}
            className={`p-2 rounded-xl border text-xs font-semibold transition-colors ${
              soundEnabled
                ? "bg-zinc-950 border-zinc-800 text-emerald-400 hover:border-emerald-500/40"
                : "bg-zinc-800 border-zinc-700 text-zinc-500"
            }`}
            title={soundEnabled ? "Âm thanh thông báo: BẬT" : "Âm thanh thông báo: TẮT"}
          >
            {soundEnabled ? <Volume2 className="w-4 h-4" /> : <VolumeX className="w-4 h-4" />}
          </button>

          {/* Mark All As Read */}
          <button
            onClick={onMarkAllAsRead}
            disabled={counts.unread === 0}
            className="flex items-center gap-1.5 px-3 py-2 rounded-xl bg-emerald-600/20 hover:bg-emerald-600/30 disabled:opacity-50 text-emerald-300 border border-emerald-500/30 text-xs font-semibold transition-colors"
          >
            <CheckCheck className="w-4 h-4" />
            <span>Đánh dấu tất cả đã đọc</span>
          </button>

          {/* Settings Button */}
          <button
            onClick={onOpenSettings}
            className="p-2 rounded-xl bg-zinc-950 hover:bg-zinc-800 border border-zinc-800 text-zinc-300 hover:text-white transition-colors"
            title="Cài đặt thông báo"
          >
            <Settings className="w-4 h-4" />
          </button>
        </div>
      </div>

      {/* Category Tabs */}
      <div className="flex items-center gap-1.5 overflow-x-auto pb-1 scrollbar-none border-b border-zinc-800">
        {tabs.map((tab) => {
          const Icon = tab.icon;
          const isActive = activeTab === tab.id;
          const isUnreadBadgeHasCount = tab.isUnreadBadge && tab.count > 0;

          return (
            <button
              key={tab.id}
              onClick={() => onTabChange(tab.id)}
              className={`flex items-center gap-2 px-4 py-2.5 rounded-t-xl text-xs sm:text-sm font-medium transition-all duration-200 border-b-2 whitespace-nowrap ${
                isActive
                  ? "border-emerald-500 text-emerald-400 bg-emerald-500/10 font-bold"
                  : "border-transparent text-zinc-400 hover:text-zinc-200 hover:bg-zinc-800/50"
              }`}
            >
              <Icon className={`w-4 h-4 ${isActive ? "text-emerald-400" : "text-zinc-400"}`} />
              <span>{tab.label}</span>

              {/* Badge count */}
              <span
                className={`px-2 py-0.5 rounded-full text-xs font-semibold ${
                  isUnreadBadgeHasCount
                    ? "bg-emerald-500 text-zinc-950 font-bold animate-pulse"
                    : isActive
                    ? "bg-emerald-500/20 text-emerald-300"
                    : "bg-zinc-800 text-zinc-400"
                }`}
              >
                {tab.count}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

