                </div>

                <div className="mt-2 flex items-baseline gap-2">
                  <span className="text-2xl font-bold text-zinc-100">{card.value}</span>
                  <span className="text-[11px] text-zinc-500">{card.subtitle}</span>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

