export function ProjectToolbar({
  filters,
  onFilterChange,
  onResetFilters,
  viewMode,
  onViewModeChange,
  onExport,
  onImport,
  members = [
    { id: "m1", name: "Hoàng Mạnh Trường" },
    { id: "m2", name: "Nguyễn Văn A" },
    { id: "m3", name: "Trần Thị B" },
