        {/* Suggestions Box */}
        <div className="w-full max-w-md p-4 rounded-xl bg-zinc-900/90 border border-zinc-800 text-left space-y-2.5 text-xs text-zinc-300">
          <div className="flex items-center gap-2 font-semibold text-amber-400">
