                      <span className="text-zinc-500 italic">Chưa kích hoạt</span>
                    )}
                  </td>

                  {/* Actions */}
                  <td className="p-3 text-right">
                    <div className="flex items-center justify-end gap-2">
                      <button
                        type="button"
                        onClick={() => onTestPing(item.id)}
