          </label>
          <div className="relative">
            <input
              id="new-password"
              type={showPassword.new ? "text" : "password"}
              value={form.newPassword}
              onChange={(e) =>
                onChangeForm({ ...form, newPassword: e.target.value })
              }
              placeholder="Nhập mật khẩu mới mạnh..."
