                  <td className="p-3 font-mono text-cyan-400 font-semibold">{item.fileSize}</td>
                  <td className="p-3 text-zinc-400 font-mono text-[11px]">{item.expiryDate}</td>
                  <td className="p-3">
                    {item.status === "ready" && (
