                      className="w-full rounded-xl bg-zinc-950 border border-zinc-800 px-3 py-2 text-xs text-zinc-200 cursor-pointer focus:border-emerald-500 focus:outline-none"
                    >
                      <option value="">Chưa phân công</option>
                      {members.map((m) => (
