"use client";

import { useState } from "react";
import { CheckSquare, Plus, Trash2, ArrowUp, ArrowDown, Loader2 } from "lucide-react";
import type { TaskChecklistItem } from "@/app/types/domain";

interface TaskChecklistModuleProps {
  workspaceId: string;
  taskId: string;
  items: TaskChecklistItem[];
  onAdd: (title: string) => Promise<void>;
  onToggle: (item: TaskChecklistItem) => Promise<void>;
  onUpdateTitle: (itemId: string, newTitle: string) => Promise<void>;
  onDelete: (item: TaskChecklistItem) => Promise<void>;
  onReorder?: (newItems: TaskChecklistItem[]) => void;
}

export function TaskChecklistModule({
  items,
  onAdd,
  onToggle,
  onUpdateTitle,
  onDelete,
  onReorder,
}: TaskChecklistModuleProps) {
  const [newTitle, setNewTitle] = useState("");
  const [adding, setAdding] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingText, setEditingText] = useState("");
  const [busyId, setBusyId] = useState<string | null>(null);

  const completedCount = items.filter((i) => i.completed).length;
  const progressPercent = items.length ? Math.round((completedCount / items.length) * 100) : 0;

  // Auto color transition for Progress Bar
  const progressBarColor =
    progressPercent === 100
      ? "bg-emerald-500"
      : progressPercent >= 50
      ? "bg-amber-500"
      : "bg-rose-500";

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    const title = newTitle.trim();
    if (!title || adding) return;

    setAdding(true);
    setNewTitle("");
    try {
      await onAdd(title);
    } finally {
      setAdding(false);
    }
  };

  const handleToggle = async (item: TaskChecklistItem) => {
    setBusyId(item.id);
    try {
      await onToggle(item);
    } finally {
      setBusyId(null);
    }
  };

  const startEdit = (item: TaskChecklistItem) => {
    setEditingId(item.id);
    setEditingText(item.title);
  };

  const saveEdit = async (itemId: string) => {
    if (!editingText.trim()) return;
    setBusyId(itemId);
    try {
      await onUpdateTitle(itemId, editingText.trim());
      setEditingId(null);
    } finally {
      setBusyId(null);
    }
  };

  const handleDelete = async (item: TaskChecklistItem) => {
    setBusyId(item.id);
    try {
      await onDelete(item);
    } finally {
      setBusyId(null);
    }
  };

  const moveItem = (index: number, direction: "up" | "down") => {
    const newIdx = direction === "up" ? index - 1 : index + 1;
    if (newIdx < 0 || newIdx >= items.length) return;
    const updated = [...items];
    const [moved] = updated.splice(index, 1);
    updated.splice(newIdx, 0, moved);
    onReorder?.(updated);
  };

  return (
    <section className="space-y-4 rounded-2xl border border-zinc-800/80 bg-zinc-900/50 p-4 backdrop-blur-md">
      {/* Header & Progress Bar */}
      <div className="space-y-2">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2 text-sm font-bold text-zinc-100">
            <CheckSquare size={16} className="text-emerald-500" />
            <h3>Danh sách công việc phụ (Checklist)</h3>
          </div>
          <span className="font-mono text-xs font-semibold text-zinc-400">
            {completedCount}/{items.length} ({progressPercent}%)
          </span>
        </div>

        {/* Progress Bar Container */}
        <div className="h-2 w-full rounded-full bg-zinc-800 overflow-hidden shadow-inner">
          <div
            className={`h-full transition-all duration-300 ${progressBarColor}`}
            style={{ width: `${progressPercent}%` }}
          />
        </div>
      </div>

      {/* Item List */}
      <div className="space-y-1.5 max-h-72 overflow-y-auto pr-1">
        {items.length > 0 ? (
          items.map((item, index) => (
            <div
              key={item.id}
              className={`group flex items-center justify-between gap-3 rounded-xl border border-zinc-800/60 p-2.5 text-xs transition-all ${
                item.completed ? "bg-zinc-950/40 opacity-70" : "bg-zinc-900 hover:bg-zinc-850 hover:border-zinc-700"
              }`}
            >
              {/* Checkbox & Title */}
              <div className="flex flex-1 items-center gap-2.5 min-w-0">
                <input
                  type="checkbox"
                  checked={item.completed}
                  disabled={busyId === item.id}
                  onChange={() => handleToggle(item)}
                  className="h-4 w-4 rounded border-zinc-700 bg-zinc-950 text-emerald-500 focus:ring-emerald-500/50 cursor-pointer"
                />

                {editingId === item.id ? (
                  <input
                    type="text"
                    value={editingText}
                    onChange={(e) => setEditingText(e.target.value)}
                    onBlur={() => saveEdit(item.id)}
                    onKeyDown={(e) => e.key === "Enter" && saveEdit(item.id)}
                    className="flex-1 rounded-lg bg-zinc-950 border border-emerald-500 px-2 py-1 text-xs text-zinc-100 focus:outline-none"
                  />
                ) : (
                  <button
                    type="button"
                    onClick={() => startEdit(item)}
                    className={`flex-1 truncate cursor-pointer text-left font-medium ${
                      item.completed ? "line-through text-zinc-500" : "text-zinc-200 hover:text-white"
                    }`}
                    title="Click để chỉnh sửa"
                  >
                    {item.title}
                  </button>
                )}
              </div>

              {/* Actions: Move Up/Down & Delete */}
              <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                {busyId === item.id ? (
                  <Loader2 size={14} className="animate-spin text-zinc-400" />
                ) : (
                  <>
                    <button
                      type="button"
                      disabled={index === 0}
                      onClick={() => moveItem(index, "up")}
                      className="p-1 text-zinc-500 hover:text-zinc-300 disabled:opacity-30"
                      title="Di chuyển lên"
                    >
                      <ArrowUp size={13} />
                    </button>
                    <button
                      type="button"
                      disabled={index === items.length - 1}
                      onClick={() => moveItem(index, "down")}
                      className="p-1 text-zinc-500 hover:text-zinc-300 disabled:opacity-30"
                      title="Di chuyển xuống"
                    >
                      <ArrowDown size={13} />
                    </button>
                    <button
                      type="button"
                      onClick={() => handleDelete(item)}
                      className="p-1 text-zinc-500 hover:text-rose-400 transition-colors"
                      title="Xóa mục này"
                    >
                      <Trash2 size={13} />
                    </button>
                  </>
                )}
              </div>
            </div>
          ))
        ) : (
          <div className="py-4 text-center text-xs text-zinc-500 italic">
            Chưa có mục checklist nào. Thêm mục mới bên dưới.
          </div>
        )}
      </div>

      {/* Add New Item Input */}
      <form onSubmit={handleAdd} className="flex items-center gap-2 pt-1">
        <input
          type="text"
          placeholder="Thêm mục checklist mới (nhấn Enter)..."
          value={newTitle}
          maxLength={240}
          onChange={(e) => setNewTitle(e.target.value)}
          className="flex-1 rounded-xl bg-zinc-950 border border-zinc-800 px-3 py-2 text-xs text-zinc-200 placeholder-zinc-500 focus:border-emerald-500 focus:outline-none focus:ring-1 focus:ring-emerald-500/40"
        />
        <button
          type="submit"
          disabled={adding || !newTitle.trim()}
          className="flex items-center gap-1 rounded-xl bg-emerald-600 px-3 py-2 text-xs font-semibold text-white hover:bg-emerald-500 disabled:opacity-40 transition-colors shadow-sm"
        >
          {adding ? <Loader2 size={14} className="animate-spin" /> : <Plus size={14} />}
          <span>Thêm</span>
        </button>
      </form>
    </section>
  );
}

/* eslint-disable jsx-a11y/click-events-have-key-events, jsx-a11y/no-static-element-interactions */
"use client";

import { useState, useMemo, useRef, useEffect } from "react";
import { MessageSquare, History, Send, Loader2, Trash2, AtSign, ShieldCheck } from "lucide-react";
import type { Member, TaskComment, ActivityEvent } from "@/app/types/domain";

interface TaskCommentModuleProps {
  comments: TaskComment[];
  activityLogs?: ActivityEvent[];
  members: Member[];
  currentUserId?: string;
  onSendComment: (body: string) => Promise<void>;
  onDeleteComment?: (commentId: string) => Promise<void>;
}

export function TaskCommentModule({
  comments,
  activityLogs = [],
  members,
  onSendComment,
  onDeleteComment,
}: TaskCommentModuleProps) {
  const [activeTab, setActiveTab] = useState<"comments" | "activity">("comments");
  const [commentBody, setCommentBody] = useState("");
  const [sending, setSending] = useState(false);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);

  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    const timer = window.setTimeout(() => setCurrentTime(Date.now()), 0);
    return () => window.clearTimeout(timer);
  }, []);

  // Extract @query for mention suggestions
  const mentionQuery = useMemo(() => {
    const match = commentBody.match(/@([^\s@]*)$/);
    return match ? match[1].toLowerCase() : null;
  }, [commentBody]);

  const filteredMembers = useMemo(() => {
    if (mentionQuery === null) return [];
    return members
      .filter(
        (m) =>
          m.name.toLowerCase().includes(mentionQuery) ||
          m.email.toLowerCase().includes(mentionQuery)
      )
      .slice(0, 5);
  }, [mentionQuery, members]);

  const handleInsertMention = (member: Member) => {
    setCommentBody((prev) => prev.replace(/@([^\s@]*)$/, `@${member.email} `));
    setShowSuggestions(false);
    textareaRef.current?.focus();
  };

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    const body = commentBody.trim();
    if (!body || sending) return;

    setSending(true);
    try {
      await onSendComment(body);
      setCommentBody("");
      setShowSuggestions(false);
    } finally {
      setSending(false);
    }
  };

  // Format relative time
  const formatTimeAgo = (isoString: string) => {
    if (currentTime === 0) return new Date(isoString).toLocaleDateString("vi-VN");
    const diffMs = currentTime - new Date(isoString).getTime();
    const mins = Math.floor(diffMs / 60000);
    if (mins < 1) return "Vừa xong";
    if (mins < 60) return `${mins} phút trước`;
    const hours = Math.floor(mins / 60);
    if (hours < 24) return `${hours} giờ trước`;
    return new Date(isoString).toLocaleDateString("vi-VN");
  };

  // Render comment body with highlighted @mentions
  const renderFormattedBody = (body: string) => {
    const parts = body.split(/(@[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,})/g);
    return parts.map((part, i) => {
      if (part.startsWith("@")) {
        return (
          <span
            key={i}
            className="inline-flex items-center gap-0.5 rounded bg-emerald-500/20 px-1.5 py-0.5 text-xs font-semibold text-emerald-300 border border-emerald-500/30"
          >
            {part}
          </span>
        );
      }
      return part;
    });
  };

  return (
    <section className="space-y-4 rounded-2xl border border-zinc-800/80 bg-zinc-900/50 p-4 backdrop-blur-md">
      {/* Tabs Header */}
      <div className="flex items-center justify-between border-b border-zinc-800 pb-3">
        <div className="flex items-center gap-2">
          <button
            onClick={() => setActiveTab("comments")}
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-bold transition-all ${
              activeTab === "comments"
                ? "bg-zinc-800 text-emerald-400 border border-zinc-700 shadow-sm"
                : "text-zinc-400 hover:text-zinc-200"
            }`}
          >
            <MessageSquare size={14} />
            <span>Bình luận ({comments.length})</span>
          </button>
          <button
            onClick={() => setActiveTab("activity")}
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-bold transition-all ${
              activeTab === "activity"
                ? "bg-zinc-800 text-emerald-400 border border-zinc-700 shadow-sm"
                : "text-zinc-400 hover:text-zinc-200"
            }`}
          >
            <History size={14} />
            <span>Lịch sử ({activityLogs.length || 3})</span>
          </button>
        </div>
      </div>

      {/* Tab 1: Comments */}
      {activeTab === "comments" && (
        <div className="space-y-4">
          {/* Comments List */}
          <div className="space-y-3 max-h-72 overflow-y-auto pr-1">
            {comments.length > 0 ? (
              comments.map((c) => (
                <div key={c.id} className="group flex items-start gap-3 rounded-xl border border-zinc-800/60 bg-zinc-900 p-3">
                  <div className="flex h-8 w-8 items-center justify-center rounded-full bg-emerald-600 font-bold text-xs text-white shrink-0">
                    {c.authorName.slice(0, 2).toUpperCase()}
                  </div>
                  <div className="flex-1 min-w-0 space-y-1">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <span className="text-xs font-bold text-zinc-100">{c.authorName}</span>
                        <span className="flex items-center gap-0.5 rounded bg-zinc-800 px-1.5 py-0.2 text-[10px] font-medium text-zinc-400">
                          <ShieldCheck size={10} className="text-emerald-400" /> Member
                        </span>
                      </div>
                      <span className="text-[10px] text-zinc-500">{formatTimeAgo(c.createdAt)}</span>
                    </div>
                    <p className="text-xs text-zinc-300 leading-relaxed break-words">
                      {renderFormattedBody(c.body)}
                    </p>
                  </div>
                  {onDeleteComment && (
                    <button
                      onClick={() => onDeleteComment(c.id)}
                      className="opacity-0 group-hover:opacity-100 transition-opacity p-1 text-zinc-500 hover:text-rose-400"
                      title="Xóa bình luận"
                    >
                      <Trash2 size={13} />
                    </button>
                  )}
                </div>
              ))
            ) : (
              <div className="py-6 text-center text-xs text-zinc-500 italic">
                Chưa có bình luận nào. Hãy là người đầu tiên để lại ý kiến!
              </div>
            )}
          </div>

          {/* Comment Input Box with Mention Popup */}
          <form onSubmit={handleSend} className="relative space-y-2">
            <div className="relative">
              <textarea
                ref={textareaRef}
                rows={3}
                placeholder="Viết bình luận... Gõ '@' để nhắc tên thành viên"
                value={commentBody}
                onChange={(e) => {
                  setCommentBody(e.target.value);
                  setShowSuggestions(true);
                }}
                className="w-full rounded-xl bg-zinc-950 border border-zinc-800 p-3 text-xs text-zinc-100 placeholder-zinc-500 focus:border-emerald-500 focus:outline-none focus:ring-1 focus:ring-emerald-500/40"
              />

              {/* @mention Suggestion Dropdown */}
              {showSuggestions && filteredMembers.length > 0 && (
                <div className="absolute bottom-full left-0 mb-1 w-64 rounded-xl border border-zinc-800 bg-zinc-900 p-1.5 shadow-2xl z-30 space-y-0.5">
                  <div className="px-2 py-1 text-[10px] font-semibold text-zinc-400 uppercase tracking-wider">
                    Nhắc tên thành viên
                  </div>
                  {filteredMembers.map((m) => (
                    <button
                      key={m.id}
                      type="button"
                      onClick={() => handleInsertMention(m)}
                      className="w-full flex items-center gap-2 px-2 py-1.5 rounded-lg hover:bg-zinc-800 text-left transition-colors"
                    >
                      <div className="flex h-6 w-6 items-center justify-center rounded-full bg-emerald-600 text-[10px] font-bold text-white">
                        {m.name.slice(0, 2).toUpperCase()}
                      </div>
                      <div className="min-w-0 flex-1">
                        <p className="text-xs font-semibold text-zinc-200 truncate">{m.name}</p>
                        <p className="text-[10px] text-zinc-500 truncate">{m.email}</p>
                      </div>
                    </button>
                  ))}
                </div>
              )}
            </div>

            <div className="flex items-center justify-between">
              <span className="text-[11px] text-zinc-500 flex items-center gap-1">
                <AtSign size={12} /> Dùng @email để tag thông báo
              </span>
              <button
                type="submit"
                disabled={sending || !commentBody.trim()}
                className="flex items-center gap-1.5 rounded-xl bg-emerald-600 px-4 py-2 text-xs font-bold text-white hover:bg-emerald-500 disabled:opacity-40 transition-colors shadow-sm"
              >
                {sending ? <Loader2 size={14} className="animate-spin" /> : <Send size={13} />}
                <span>Gửi bình luận</span>
              </button>
            </div>
          </form>
        </div>
      )}

      {/* Tab 2: Activity Log Timeline */}
      {activeTab === "activity" && (
        <div className="space-y-3 py-1">
          {activityLogs.length > 0 ? (
            activityLogs.map((log) => (
              <div key={log.id} className="flex items-start gap-3 text-xs text-zinc-300">
                <div className="h-2 w-2 rounded-full bg-emerald-400 mt-1.5 shrink-0" />
                <div>
                  <p className="font-semibold text-zinc-200">
                    {log.actorName || "Thành viên"} <span className="font-normal text-zinc-400">{log.action}</span>
                  </p>
                  <span className="text-[10px] text-zinc-500">{formatTimeAgo(log.createdAt)}</span>
                </div>
              </div>
            ))
          ) : (
            <div className="space-y-3 text-xs text-zinc-400">
              <div className="flex items-start gap-3">
                <div className="h-2 w-2 rounded-full bg-emerald-400 mt-1.5 shrink-0" />
                <div>
                  <p className="font-semibold text-zinc-200">
                    Hùng Hoàng <span className="font-normal text-zinc-400">đã tạo công việc này</span>
                  </p>
                  <span className="text-[10px] text-zinc-500">Hôm qua lúc 14:30</span>
                </div>
              </div>
              <div className="flex items-start gap-3">
                <div className="h-2 w-2 rounded-full bg-blue-400 mt-1.5 shrink-0" />
                <div>
                  <p className="font-semibold text-zinc-200">
                    Nguyễn Văn <span className="font-normal text-zinc-400">đã chuyển trạng thái sang Đang làm</span>
                  </p>
                  <span className="text-[10px] text-zinc-500">5 giờ trước</span>
                </div>
              </div>
            </div>
          )}
        </div>
      )}
    </section>
  );
}

/* eslint-disable jsx-a11y/click-events-have-key-events, jsx-a11y/no-static-element-interactions */
"use client";

import { startTransition, useState, useEffect, useCallback, useRef } from "react";
import {
  X,
  Copy,
  Check,
  Loader2,
  FileText,
  ChevronRight,
} from "lucide-react";
import type { TaskSummary, TaskAttachment, TaskChecklistItem, TaskComment, Member } from "@/app/types/domain";
import { taskService } from "@/app/services/task-service";
import { collaborationService } from "@/app/services/collaboration-service";
import { TaskChecklistModule } from "./TaskChecklistModule";
import { TaskAttachmentModule } from "./TaskAttachmentModule";
import { TaskCommentModule } from "./TaskCommentModule";
import { TaskSidebarAttributes } from "./TaskSidebarAttributes";

interface TaskDetailDrawerProps {
  workspaceId: string;
  taskId: string;
  isOpen: boolean;
  onClose: () => void;
  initialTask?: TaskSummary;
}

export function TaskDetailDrawer({
  workspaceId,
  taskId,
  isOpen,
  onClose,
  initialTask,
}: TaskDetailDrawerProps) {
  const [task, setTask] = useState<TaskSummary | null>(initialTask || null);
  const [loading, setLoading] = useState(!initialTask);
  const [checklist, setChecklist] = useState<TaskChecklistItem[]>([]);
  const [attachments, setAttachments] = useState<TaskAttachment[]>([]);
  const [comments, setComments] = useState<TaskComment[]>([]);
  const [members, setMembers] = useState<Member[]>([]);

  // Auto-save state
  const [savingStatus, setSavingStatus] = useState<"idle" | "saving" | "saved" | "error">("idle");
  const [copiedLink, setCopiedLink] = useState(false);

  // Text inputs for title & description
  const [title, setTitle] = useState(initialTask?.title || "");
  const [description, setDescription] = useState(initialTask?.description || "");
  const [isEditingDesc, setIsEditingDesc] = useState(false);
  const descriptionInputRef = useRef<HTMLTextAreaElement>(null);

  // ESC key to close
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape" && isOpen) {
        onClose();
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, onClose]);

  // Load task detail, checklist, attachments, comments
  useEffect(() => {
    if (!isOpen || !taskId) return;

    let isMounted = true;
    startTransition(() => setLoading(true));

    // If reference task (e.g. ref-1) handle mock data
    if (taskId.startsWith("ref-")) {
      const mockTask: TaskSummary = {
        id: taskId,
        workspaceId,
        projectId: "p1",
        projectName: "SaaS TaskFlow",
        boardId: "b1",
        columnId: "todo",
        columnName: "Cần làm",
        title: initialTask?.title || "Thiết kế hệ thống Design Tokens",
        description: initialTask?.description || "Đồng bộ hóa các giá trị màu sắc, typography và spacing cho ứng dụng mới.",
        priority: "HIGH",
        dueAt: "2026-10-25",
        assigneeIds: [],
        version: 1,
        archivedAt: null,
        tone: "green",
        checklistTotal: 4,
        checklistCompleted: 2,
      };
      startTransition(() => {
        setTask(mockTask);
        setTitle(mockTask.title);
        setDescription(mockTask.description);
        setChecklist([
          { id: "c1", taskId, title: "Xác định bảng màu Primary & Surface", completed: true, position: 0, createdByUserId: null, completedByUserId: null, completedAt: new Date().toISOString(), createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() },
          { id: "c2", taskId, title: "Tạo typography scale cho Dark Mode", completed: true, position: 1, createdByUserId: null, completedByUserId: null, completedAt: new Date().toISOString(), createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() },
          { id: "c3", taskId, title: "Xây dựng component TaskCard & KanbanColumn", completed: false, position: 2, createdByUserId: null, completedByUserId: null, completedAt: null, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() },
          { id: "c4", taskId, title: "Kiểm thử responsive trên Mobile và Tablet", completed: false, position: 3, createdByUserId: null, completedByUserId: null, completedAt: null, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() },
        ]);
        setAttachments([
          { id: "a1", taskId, fileName: "design-tokens-v1.pdf", mimeType: "application/pdf", size: 1240000, uploadedByUserId: null, createdAt: new Date().toISOString() },
          { id: "a2", taskId, fileName: "darkmode-palette.png", mimeType: "image/png", size: 450000, uploadedByUserId: null, createdAt: new Date().toISOString() },
        ]);
        setComments([
          { id: "m1", taskId, body: "Đã xong phần thiết kế token màu sắc rồi nhé @hoanghungcri0101@gmail.com!", authorName: "Nguyễn Văn", authorUserId: "u1", hidden: false, deleted: false, createdAt: new Date(Date.now() - 3600000).toISOString(), updatedAt: new Date().toISOString() },
        ]);
        setMembers([
          { id: "m1", userId: "u1", name: "Nguyễn Văn", email: "nguyenvan@example.com", role: "MEMBER", status: "ACTIVE", createdAt: new Date().toISOString() },
          { id: "m2", userId: "u2", name: "Hoàng Long", email: "hoanglong@example.com", role: "ADMIN", status: "ACTIVE", createdAt: new Date().toISOString() },
          { id: "m3", userId: "u3", name: "Trần Phương", email: "tranphuong@example.com", role: "MEMBER", status: "ACTIVE", createdAt: new Date().toISOString() },
        ]);
        setLoading(false);
      });
      return;
    }

    // Fetch real data from API
    Promise.all([
      taskService.get(workspaceId, taskId),
      taskService.checklist(workspaceId, taskId).catch(() => []),
      taskService.attachments(workspaceId, taskId).catch(() => []),
      taskService.comments(workspaceId, taskId).catch(() => []),
      collaborationService.members(workspaceId).catch(() => []),
    ])
      .then(([fetchedTask, fetchedChecklist, fetchedAttachments, fetchedComments, fetchedMembers]) => {
        if (!isMounted) return;
        setTask(fetchedTask);
        setTitle(fetchedTask.title);
        setDescription(fetchedTask.description || "");
        setChecklist(fetchedChecklist);
        setAttachments(fetchedAttachments);
        setComments(fetchedComments);
        setMembers(fetchedMembers);
      })
      .catch((err) => console.error(err))
      .finally(() => {
        if (isMounted) setLoading(false);
      });

    return () => {
      isMounted = false;
    };
  }, [isOpen, taskId, workspaceId, initialTask]);

  // Debounced Auto-save for Title & Description
  const saveTaskFields = useCallback(
    async (updated: Partial<TaskSummary>) => {
      if (!task || taskId.startsWith("ref-")) {
        setSavingStatus("saved");
        setTimeout(() => setSavingStatus("idle"), 2000);
        return;
      }

      setSavingStatus("saving");
      try {
        const result = await taskService.update(workspaceId, taskId, {
          expectedVersion: task.version,
          title: updated.title ?? task.title,
          description: updated.description ?? task.description,
          priority: updated.priority ?? task.priority,
          dueAt: updated.dueAt ?? task.dueAt,
          columnId: updated.columnId ?? task.columnId,
        });
        setTask(result);
        setSavingStatus("saved");
        setTimeout(() => setSavingStatus("idle"), 2500);
      } catch (err) {
        console.error(err);
        setSavingStatus("error");
      }
    },
    [task, taskId, workspaceId]
  );

  const handleTitleBlur = () => {
    if (task && title.trim() !== task.title) {
      setTask({ ...task, title: title.trim() });
      saveTaskFields({ title: title.trim() });
    }
  };

  const handleDescBlur = () => {
    if (task && description !== task.description) {
      setTask({ ...task, description });
      saveTaskFields({ description });
    }
    setIsEditingDesc(false);
  };

  const handleCopyLink = () => {
    const url = `${window.location.origin}/app/tasks/${taskId}`;
    navigator.clipboard.writeText(url);
    setCopiedLink(true);
    setTimeout(() => setCopiedLink(false), 2000);
  };

  // ── Checklist Handlers ─────────────────────────────────────────
  const handleAddChecklist = async (itemTitle: string) => {
    if (taskId.startsWith("ref-")) {
      const newItem: TaskChecklistItem = {
        id: `c_${Date.now()}`,
        taskId,
        title: itemTitle,
        completed: false,
        position: checklist.length,
        createdByUserId: null,
        completedByUserId: null,
        completedAt: null,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      };
      setChecklist((prev) => [...prev, newItem]);
      return;
    }
    const created = await taskService.createChecklistItem(workspaceId, taskId, itemTitle);
    setChecklist((prev) => [...prev, created]);
  };

  const handleToggleChecklist = async (item: TaskChecklistItem) => {
    const updatedStatus = !item.completed;
    setChecklist((prev) =>
      prev.map((i) => (i.id === item.id ? { ...i, completed: updatedStatus } : i))
    );
    if (!taskId.startsWith("ref-")) {
      await taskService.updateChecklistItem(workspaceId, taskId, item.id, { completed: updatedStatus });
    }
  };

  const handleUpdateChecklistTitle = async (itemId: string, newTitle: string) => {
    setChecklist((prev) =>
      prev.map((i) => (i.id === itemId ? { ...i, title: newTitle } : i))
    );
    if (!taskId.startsWith("ref-")) {
      await taskService.updateChecklistItem(workspaceId, taskId, itemId, { title: newTitle });
    }
  };

  const handleDeleteChecklist = async (item: TaskChecklistItem) => {
    setChecklist((prev) => prev.filter((i) => i.id !== item.id));
    if (!taskId.startsWith("ref-")) {
      await taskService.deleteChecklistItem(workspaceId, taskId, item.id);
    }
  };

  // ── Attachment Handlers ────────────────────────────────────────
  const handleUploadAttachment = async (file: File) => {
    if (taskId.startsWith("ref-")) {
      const newAtt: TaskAttachment = {
        id: `att_${Date.now()}`,
        taskId,
        fileName: file.name,
        mimeType: file.type,
        size: file.size,
        uploadedByUserId: null,
        createdAt: new Date().toISOString(),
      };
      setAttachments((prev) => [...prev, newAtt]);
      return;
    }
    const created = await taskService.uploadAttachment(workspaceId, taskId, file);
    setAttachments((prev) => [...prev, created]);
  };

  const handleDownloadAttachment = async (item: TaskAttachment) => {
    if (taskId.startsWith("ref-")) {
      alert(`Đang tải file mẫu: ${item.fileName}`);
      return;
    }
    const res = await taskService.attachmentDownload(workspaceId, taskId, item.id);
    window.location.assign(res.url);
  };

  const handleDeleteAttachment = async (attachmentId: string) => {
    setAttachments((prev) => prev.filter((a) => a.id !== attachmentId));
    if (!taskId.startsWith("ref-")) {
      await taskService.deleteAttachment(workspaceId, taskId, attachmentId);
    }
  };

  // ── Comment Handlers ───────────────────────────────────────────
  const handleSendComment = async (body: string) => {
    if (taskId.startsWith("ref-")) {
      const newCmt: TaskComment = {
        id: `cmt_${Date.now()}`,
        taskId,
        body,
        authorName: "Hùng Hoàng (Bạn)",
        authorUserId: "u_me",
        hidden: false,
        deleted: false,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      };
      setComments((prev) => [...prev, newCmt]);
      return;
    }
    const created = await taskService.comment(workspaceId, taskId, body);
    setComments((prev) => [...prev, created]);
  };

  const handleDeleteComment = async (commentId: string) => {
    setComments((prev) => prev.filter((c) => c.id !== commentId));
    if (!taskId.startsWith("ref-")) {
      await taskService.deleteComment(workspaceId, commentId);
    }
  };

  if (!isOpen) return null;

  return (
    <>
      {/* Backdrop overlay */}
      <div
        onClick={onClose}
        onKeyDown={(event) => {
          if (event.key === "Enter" || event.key === " ") onClose();
        }}
        role="button"
        tabIndex={0}
        aria-label="Đóng chi tiết công việc"
        className="fixed inset-0 z-40 bg-black/70 backdrop-blur-sm transition-opacity animate-fadeIn"
      />

      {/* Slide-over Drawer Container */}
      <div className="fixed top-0 right-0 z-50 h-full w-full lg:w-[68vw] xl:w-[65vw] max-w-5xl bg-zinc-950 border-l border-zinc-800/80 text-zinc-100 shadow-2xl flex flex-col transition-all duration-300 transform translate-x-0">
        {/* ── Top Header Bar ── */}
        <div className="flex items-center justify-between border-b border-zinc-800/80 px-6 py-4 bg-zinc-900/60 backdrop-blur-md">
          {/* Breadcrumb */}
          <div className="flex items-center gap-2 text-xs text-zinc-400">
            <span className="font-semibold text-zinc-300">
              {task?.projectName || "SaaS TaskFlow"}
            </span>
            <ChevronRight size={14} className="text-zinc-600" />
            <span className="rounded-md bg-zinc-800 px-2 py-0.5 font-medium text-emerald-400">
              {task?.columnName || "Chi tiết công việc"}
            </span>
          </div>

          {/* Header Right Actions & Auto-save Status */}
          <div className="flex items-center gap-3">
            {/* Auto-save status feedback badge */}
            <div className="flex items-center gap-1.5 text-xs text-zinc-400">
              {savingStatus === "saving" && (
                <>
                  <Loader2 size={13} className="animate-spin text-amber-400" />
                  <span className="text-amber-400 font-medium">Đang lưu...</span>
                </>
              )}
              {savingStatus === "saved" && (
                <>
                  <Check size={13} className="text-emerald-400" />
                  <span className="text-emerald-400 font-medium">Đã lưu tất cả thay đổi</span>
                </>
              )}
            </div>

            {/* Copy Link Button */}
            <button
              onClick={handleCopyLink}
              className="flex items-center gap-1 rounded-xl border border-zinc-800 bg-zinc-900 px-3 py-1.5 text-xs font-semibold text-zinc-300 hover:bg-zinc-800 hover:text-white transition-colors"
              title="Sao chép link task"
            >
              {copiedLink ? <Check size={14} className="text-emerald-400" /> : <Copy size={14} />}
              <span>{copiedLink ? "Đã chép" : "Copy link"}</span>
            </button>

            {/* Close ESC Button */}
            <button
              onClick={onClose}
              className="flex h-8 w-8 items-center justify-center rounded-xl bg-zinc-900 border border-zinc-800 text-zinc-400 hover:bg-zinc-800 hover:text-white transition-colors"
              title="Đóng (Phím ESC)"
            >
              <X size={18} />
            </button>
          </div>
        </div>

        {/* ── Main Body (2 Columns) ── */}
        {loading ? (
          <div className="flex flex-1 items-center justify-center">
            <Loader2 size={32} className="animate-spin text-emerald-500 mb-2" />
          </div>
        ) : (
          <div className="flex flex-1 overflow-hidden">
            {/* ── LEFT COLUMN (65% width) ── */}
            <div className="flex-1 overflow-y-auto p-6 space-y-6 lg:border-r border-zinc-800/80 pr-6">
              {/* Task Title (Inline Editable) */}
              <div className="space-y-1">
                <input
                  type="text"
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  onBlur={handleTitleBlur}
                  placeholder="Nhập tiêu đề công việc..."
                  className="w-full rounded-xl bg-transparent border border-transparent hover:border-zinc-800 focus:border-emerald-500 px-2 py-1 text-xl font-extrabold text-zinc-100 placeholder-zinc-600 focus:outline-none focus:ring-1 focus:ring-emerald-500/40 transition-all"
                />
              </div>

              {/* Description (Rich/Markdown Textarea with Preview) */}
              <div className="space-y-2 rounded-2xl border border-zinc-800/80 bg-zinc-900/50 p-4 backdrop-blur-md">
                <div className="flex items-center justify-between">
                  <h3 className="text-sm font-bold text-zinc-100 flex items-center gap-2">
                    <FileText size={16} className="text-emerald-500" /> Mô tả công việc
                  </h3>
                  <button
                    onClick={() => setIsEditingDesc(!isEditingDesc)}
                    className="text-xs font-semibold text-emerald-400 hover:text-emerald-300"
                  >
                    {isEditingDesc ? "Xem trước" : "Chỉnh sửa"}
                  </button>
                </div>

                {isEditingDesc ? (
                  <textarea
                    ref={descriptionInputRef}
                    rows={4}
                    value={description}
                    onChange={(e) => setDescription(e.target.value)}
                    onBlur={handleDescBlur}
                    placeholder="Thêm mô tả chi tiết công việc..."
                    className="w-full rounded-xl bg-zinc-950 border border-zinc-800 p-3 text-xs text-zinc-200 placeholder-zinc-600 focus:border-emerald-500 focus:outline-none"
                  />
                ) : (
                  <div
                    onClick={() => setIsEditingDesc(true)}
                    onKeyDown={(event) => {
                      if (event.key === "Enter" || event.key === " ") setIsEditingDesc(true);
                    }}
                    role="button"
                    tabIndex={0}
                    aria-label="Chỉnh sửa mô tả công việc"
                    className="min-h-[70px] rounded-xl bg-zinc-950/60 border border-zinc-800/60 p-3 text-xs text-zinc-300 leading-relaxed cursor-pointer hover:border-zinc-700 transition-colors"
                  >
                    {description ? (
                      <p className="whitespace-pre-wrap">{description}</p>
                    ) : (
                      <span className="text-zinc-500 italic">Bấm vào đây để thêm mô tả chi tiết...</span>
                    )}
                  </div>
                )}
              </div>

              {/* Checklist Module */}
              <TaskChecklistModule
                workspaceId={workspaceId}
                taskId={taskId}
                items={checklist}
                onAdd={handleAddChecklist}
                onToggle={handleToggleChecklist}
                onUpdateTitle={handleUpdateChecklistTitle}
                onDelete={handleDeleteChecklist}
                onReorder={(newItems) => setChecklist(newItems)}
              />

              {/* Attachments Module */}
              <TaskAttachmentModule
                attachments={attachments}
                onUpload={handleUploadAttachment}
                onDownload={handleDownloadAttachment}
                onDelete={handleDeleteAttachment}
              />

              {/* Comments & Activity Log Module */}
              <TaskCommentModule
                comments={comments}
                members={members}
                onSendComment={handleSendComment}
                onDeleteComment={handleDeleteComment}
              />
            </div>

            {/* ── RIGHT COLUMN (35% width Sidebar) ── */}
            <div className="w-80 lg:w-96 shrink-0 overflow-y-auto p-6 bg-zinc-950/80">
              {task && (
                <TaskSidebarAttributes
                  task={task}
                  members={members}
                  onUpdate={saveTaskFields}
                />
              )}
            </div>
          </div>
        )}
      </div>
    </>
  );
}

/* eslint-disable jsx-a11y/click-events-have-key-events, jsx-a11y/no-static-element-interactions */
"use client";

import { useState } from "react";
import {
  User,
  Users,
  CalendarDays,
  Tag,
  AlertTriangle,
  ChevronDown,
  Search,
  Check,
  X,
  Sparkles,
} from "lucide-react";
import type { Member, TaskSummary } from "@/app/types/domain";

interface TaskSidebarAttributesProps {
  task: TaskSummary;
  members: Member[];
  onUpdate: (updatedFields: Partial<TaskSummary>) => Promise<void>;
}

export function TaskSidebarAttributes({
  task,
  members,
  onUpdate,
}: TaskSidebarAttributesProps) {
  const [showAssigneeDropdown, setShowAssigneeDropdown] = useState(false);
  const [showWatchersDropdown, setShowWatchersDropdown] = useState(false);
  const [assigneeSearch, setAssigneeSearch] = useState("");
  const [selectedAssignees, setSelectedAssignees] = useState<string[]>(
    task.assigneeIds || []
  );
  const [selectedTags, setSelectedTags] = useState<string[]>(["UI/UX", "System"]);
  const [now] = useState(() => Date.now());

  const priorityBadgeStyles = {
    URGENT: "bg-rose-500/15 text-rose-400 border-rose-500/30",
    HIGH: "bg-rose-500/10 text-rose-300 border-rose-500/20",
    MEDIUM: "bg-amber-500/10 text-amber-300 border-amber-500/20",
    LOW: "bg-emerald-500/10 text-emerald-300 border-emerald-500/20",
  };

  const isOverdue =
    task.dueAt && new Date(task.dueAt).getTime() < now && task.columnName !== "Hoàn thành";

  const handleStatusChange = async (newColumnId: string) => {
    await onUpdate({ columnId: newColumnId });
  };

  const handlePriorityChange = async (newPriority: TaskSummary["priority"]) => {
    await onUpdate({ priority: newPriority });
  };

  const handleDueDateChange = async (newDate: string) => {
    await onUpdate({ dueAt: newDate || null });
  };

  const toggleAssignee = async (memberId: string) => {
    const updated = selectedAssignees.includes(memberId)
      ? selectedAssignees.filter((id) => id !== memberId)
      : [...selectedAssignees, memberId];
    setSelectedAssignees(updated);
    await onUpdate({ assigneeIds: updated });
  };

  const filteredMembers = members.filter(
    (m) =>
      m.name.toLowerCase().includes(assigneeSearch.toLowerCase()) ||
      m.email.toLowerCase().includes(assigneeSearch.toLowerCase())
  );

  return (
    <aside className="space-y-5 rounded-2xl border border-zinc-800/80 bg-zinc-900/40 p-4 backdrop-blur-md">
      <div className="flex items-center justify-between border-b border-zinc-800 pb-3">
        <h3 className="text-xs font-bold uppercase tracking-wider text-zinc-400">Thuộc tính công việc</h3>
      </div>

      {/* ── 1. Trạng thái (Status Dropdown) ── */}
      <div className="space-y-1.5">
        <label htmlFor="task-sidebar-status" className="text-xs font-semibold text-zinc-300 flex items-center gap-1.5">
          <Sparkles size={14} className="text-emerald-400" /> Trạng thái
        </label>
        <select
          id="task-sidebar-status"
          value={task.columnId}
          onChange={(e) => handleStatusChange(e.target.value)}
          className="w-full rounded-xl bg-zinc-950 border border-zinc-800 px-3 py-2 text-xs font-semibold text-zinc-200 cursor-pointer focus:border-emerald-500 focus:outline-none"
        >
          <option value="todo">🔘 Cần làm (To-do)</option>
          <option value="in-progress">🔵 Đang làm (In Progress)</option>
          <option value="in-review">🟡 Đang đánh giá (In Review)</option>
          <option value="completed">🟢 Hoàn thành (Done)</option>
        </select>
      </div>

      {/* ── 2. Độ ưu tiên (Priority Select) ── */}
      <div className="space-y-1.5">
        <label htmlFor="task-sidebar-priority" className="text-xs font-semibold text-zinc-300">Mức độ ưu tiên</label>
        <select
          id="task-sidebar-priority"
          value={task.priority}
          onChange={(e) => handlePriorityChange(e.target.value as TaskSummary["priority"])}
          className={`w-full rounded-xl bg-zinc-950 border border-zinc-800 px-3 py-2 text-xs font-bold cursor-pointer focus:border-emerald-500 focus:outline-none ${
            priorityBadgeStyles[task.priority] || priorityBadgeStyles.MEDIUM
          }`}
        >
          <option value="URGENT" className="bg-zinc-900 text-rose-400">🔴 Khẩn cấp (Urgent)</option>
          <option value="HIGH" className="bg-zinc-900 text-rose-300">🟠 Cao (High)</option>
          <option value="MEDIUM" className="bg-zinc-900 text-amber-300">🟡 Trung bình (Medium)</option>
          <option value="LOW" className="bg-zinc-900 text-emerald-300">🟢 Thấp (Low)</option>
        </select>
      </div>

      {/* ── 3. Người thực hiện (Assignee Multi-select) ── */}
      <div className="space-y-1.5 relative">
        <div className="text-xs font-semibold text-zinc-300 flex items-center justify-between">
          <span className="flex items-center gap-1.5"><User size={14} className="text-blue-400" /> Người thực hiện</span>
          <span className="text-[10px] text-zinc-500">{selectedAssignees.length} đã chọn</span>
        </div>

        <button
          id="task-sidebar-assignees"
          type="button"
          onClick={() => setShowAssigneeDropdown(!showAssigneeDropdown)}
          className="w-full flex items-center justify-between rounded-xl bg-zinc-950 border border-zinc-800 px-3 py-2 text-xs text-zinc-200 hover:border-zinc-700 transition-colors"
        >
          <div className="flex items-center gap-1.5 overflow-hidden">
            {selectedAssignees.length > 0 ? (
              members
                .filter((m) => selectedAssignees.includes(m.id))
                .slice(0, 3)
                .map((m) => (
                  <span key={m.id} className="flex h-5 w-5 items-center justify-center rounded-full bg-emerald-600 text-[9px] font-bold text-white shrink-0">
                    {m.name.slice(0, 2).toUpperCase()}
                  </span>
                ))
            ) : (
              <span className="text-zinc-500 italic">Chưa giao cho ai</span>
            )}
          </div>
          <ChevronDown size={14} className="text-zinc-500" />
        </button>

        {showAssigneeDropdown && (
          <div className="absolute top-full left-0 right-0 mt-1 rounded-xl border border-zinc-800 bg-zinc-950 p-2 shadow-2xl z-30 space-y-2">
            <div className="relative">
              <Search size={13} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-zinc-500" />
              <input
                type="text"
                placeholder="Tìm thành viên..."
                value={assigneeSearch}
                onChange={(e) => setAssigneeSearch(e.target.value)}
                className="w-full rounded-lg bg-zinc-900 border border-zinc-800 pl-7 pr-2 py-1.5 text-xs text-zinc-200 placeholder-zinc-500 focus:outline-none"
              />
            </div>
            <div className="max-h-40 overflow-y-auto space-y-1">
              {filteredMembers.map((m) => {
                const isChecked = selectedAssignees.includes(m.id);
                return (
                  <button
                    key={m.id}
                    type="button"
                    onClick={() => toggleAssignee(m.id)}
                    className="w-full flex items-center justify-between px-2 py-1.5 rounded-lg hover:bg-zinc-800 text-xs text-left"
                  >
                    <div className="flex items-center gap-2">
                      <div className="flex h-5 w-5 items-center justify-center rounded-full bg-emerald-600 text-[9px] font-bold text-white">
                        {m.name.slice(0, 2).toUpperCase()}
                      </div>
                      <span className="font-medium text-zinc-200">{m.name}</span>
                    </div>
                    {isChecked && <Check size={14} className="text-emerald-400" />}
                  </button>
                );
              })}
            </div>
          </div>
        )}
      </div>

      {/* ── 4. Người theo dõi (Watchers Multi-select) ── */}
      <div className="space-y-1.5 relative">
        <div className="text-xs font-semibold text-zinc-300 flex items-center justify-between">
          <span className="flex items-center gap-1.5"><Users size={14} className="text-purple-400" /> Người theo dõi</span>
        </div>
        <button
          id="task-sidebar-watchers"
          type="button"
          onClick={() => setShowWatchersDropdown(!showWatchersDropdown)}
          className="w-full flex items-center justify-between rounded-xl bg-zinc-950 border border-zinc-800 px-3 py-2 text-xs text-zinc-200 hover:border-zinc-700 transition-colors"
        >
          <span className="text-zinc-500 italic">Thêm người nhận thông báo...</span>
          <ChevronDown size={14} className="text-zinc-500" />
        </button>
      </div>

      {/* ── 5. Hạn hoàn thành (Due Date Picker) ── */}
      <div className="space-y-1.5">
        <div className="flex items-center justify-between">
          <label htmlFor="task-sidebar-due-date" className="text-xs font-semibold text-zinc-300 flex items-center gap-1.5">
            <CalendarDays size={14} className="text-amber-400" /> Hạn hoàn thành
          </label>
          {isOverdue && (
            <span className="flex items-center gap-1 rounded bg-rose-500/20 px-1.5 py-0.5 text-[10px] font-bold text-rose-400 border border-rose-500/30">
              <AlertTriangle size={11} /> Quá hạn
            </span>
          )}
        </div>
        <input
          id="task-sidebar-due-date"
          type="date"
          value={task.dueAt ? task.dueAt.slice(0, 10) : ""}
          onChange={(e) => handleDueDateChange(e.target.value)}
          className="w-full rounded-xl bg-zinc-950 border border-zinc-800 px-3 py-2 text-xs text-zinc-200 focus:border-emerald-500 focus:outline-none cursor-pointer"
        />
      </div>

      {/* ── 6. Nhãn / Tags Selector ── */}
      <div className="space-y-1.5">
        <div className="text-xs font-semibold text-zinc-300 flex items-center gap-1.5">
          <Tag size={14} className="text-emerald-400" /> Nhãn / Tags
        </div>
        <div className="flex flex-wrap gap-1.5">
          {selectedTags.map((tag) => (
            <span key={tag} className="inline-flex items-center gap-1 px-2 py-0.5 rounded-lg text-xs font-medium bg-zinc-800 text-zinc-300 border border-zinc-700">
              {tag}
              <button type="button" onClick={() => setSelectedTags(selectedTags.filter((t) => t !== tag))} className="text-zinc-500 hover:text-white">
                <X size={11} />
              </button>
            </span>
          ))}
        </div>
      </div>

      {/* ── 7. Metadata Info ── */}
      <div className="border-t border-zinc-800 pt-4 space-y-2 text-[11px] text-zinc-500">
        <div className="flex justify-between">
          <span>Người tạo:</span>
          <span className="font-semibold text-zinc-300">Hùng Hoàng</span>
        </div>
        <div className="flex justify-between">
          <span>Ngày tạo:</span>
          <span className="text-zinc-400">25 Th10, 2026</span>
        </div>
        <div className="flex justify-between">
          <span>Cập nhật lần cuối:</span>
          <span className="text-zinc-400">Vừa xong</span>
        </div>
      </div>
    </aside>
  );
}

/* eslint-disable jsx-a11y/click-events-have-key-events, jsx-a11y/no-static-element-interactions */
"use client";

import { useMemo, useState } from "react";
import { CheckSquare, Download, MessageCircle, Paperclip, Plus, Trash2, Upload } from "lucide-react";
import type { Member, TaskAttachment, TaskChecklistItem, TaskComment, TaskSummary, WorkspaceRole } from "@/app/types/domain";
import { taskService } from "@/app/services/task-service";
import { collaborationService } from "@/app/services/collaboration-service";
import { ApiClientError } from "@/app/services/http-client";
import { useConnectionSync } from "@/app/hooks/use-connection-sync";
import { Badge, Button, Field } from "@/app/components/ui";
import { ConnectionStatus } from "./kanban-board";

export function TaskEditor({
  workspaceId,
  workspaceRole,
  initialTask,
  initialComments,
  initialAttachments,
  initialChecklist,
  refetch,
}: {
  workspaceId: string;
  workspaceRole: WorkspaceRole;
  initialTask: TaskSummary;
  initialComments: TaskComment[];
  initialAttachments: TaskAttachment[];
  initialChecklist: TaskChecklistItem[];
  refetch: () => void;
}) {
  void workspaceRole;
  const [task, setTask] = useState(initialTask);
  const [comments, setComments] = useState(initialComments);
  const [attachments, setAttachments] = useState(initialAttachments);
  const [checklist, setChecklist] = useState(initialChecklist);
  const [members, setMembers] = useState<Member[]>([]);
  const [saving, setSaving] = useState(false);
  const [commenting, setCommenting] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [addingChecklist, setAddingChecklist] = useState(false);
  const [checklistBusy, setChecklistBusy] = useState("");
  const [attachmentBusy, setAttachmentBusy] = useState("");
  const [message, setMessage] = useState("");
  const [commentBody, setCommentBody] = useState("");
  const [checklistTitle, setChecklistTitle] = useState("");
  const connection = useConnectionSync(refetch);

  const completedChecklist = checklist.filter((item) => item.completed).length;
  const checklistProgress = checklist.length ? Math.round((completedChecklist / checklist.length) * 100) : 0;

  const suggestions = useMemo(() => {
    const query = commentBody.match(/@([^\s@]*)$/)?.[1]?.toLowerCase();
    if (query === undefined) return [];
    return members
      .filter((member) => member.email.toLowerCase().includes(query) || member.name.toLowerCase().includes(query))
      .slice(0, 5);
  }, [commentBody, members]);

  async function save(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSaving(true);
    setMessage("");
    const form = new FormData(event.currentTarget);
    try {
      const updated = await taskService.update(workspaceId, task.id, {
        expectedVersion: task.version,
        title: String(form.get("title")),
        description: String(form.get("description")),
        priority: String(form.get("priority")) as TaskSummary["priority"],
        dueAt: String(form.get("dueAt")) || null,
      });
      setTask(updated);
      setMessage("Đã lưu thay đổi.");
    } catch (value) {
      if (value instanceof ApiClientError && value.code === "TASK_VERSION_CONFLICT") {
        setMessage("Công việc vừa được cập nhật ở nơi khác. Đang tải phiên bản mới...");
        refetch();
      } else {
        setMessage(value instanceof Error ? value.message : "Không thể lưu thay đổi");
      }
    } finally {
      setSaving(false);
    }
  }

  async function sendComment(event: React.FormEvent) {
    event.preventDefault();
    if (!commentBody.trim()) return;
    setCommenting(true);
    setMessage("");
    try {
      const created = await taskService.comment(workspaceId, task.id, commentBody);
      setComments((items) => [...items, created]);
      setCommentBody("");
    } catch (value) {
      setMessage(value instanceof Error ? value.message : "Không thể gửi bình luận");
    } finally {
      setCommenting(false);
    }
  }

  function openSuggestions() {
    if (!members.length) collaborationService.members(workspaceId).then(setMembers).catch(() => setMembers([]));
  }

  function chooseMention(member: Member) {
    setCommentBody((value) => value.replace(/@([^\s@]*)$/, `@${member.email} `));
  }

  async function uploadAttachment(event: React.ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];
    event.target.value = "";
    if (!file) return;
    if (file.size > 10 * 1024 * 1024) {
      setMessage("Tệp tối đa 10 MB.");
      return;
    }
    setUploading(true);
    setMessage("");
    try {
      const created = await taskService.uploadAttachment(workspaceId, task.id, file);
      setAttachments((items) => [...items, created]);
      setMessage("Đã tải tệp lên an toàn.");
    } catch (value) {
      setMessage(value instanceof Error ? value.message : "Không thể tải tệp lên");
    } finally {
      setUploading(false);
    }
  }

  async function downloadAttachment(item: TaskAttachment) {
    setAttachmentBusy(item.id);
    setMessage("");
    try {
      const result = await taskService.attachmentDownload(workspaceId, task.id, item.id);
      window.location.assign(result.url);
    } catch (value) {
      setMessage(value instanceof Error ? value.message : "Không thể tải tệp");
    } finally {
      setAttachmentBusy("");
    }
  }

  async function removeAttachment(item: TaskAttachment) {
    setAttachmentBusy(item.id);
    setMessage("");
    try {
      await taskService.deleteAttachment(workspaceId, task.id, item.id);
      setAttachments((items) => items.filter((value) => value.id !== item.id));
      setMessage("Đã xóa tệp.");
    } catch (value) {
      setMessage(value instanceof Error ? value.message : "Không thể xóa tệp");
    } finally {
      setAttachmentBusy("");
    }
  }

  async function addChecklistItem(event: React.FormEvent) {
    event.preventDefault();
    const title = checklistTitle.trim();
    if (!title) return;
    setAddingChecklist(true);
    setMessage("");
    try {
      const created = await taskService.createChecklistItem(workspaceId, task.id, title);
      setChecklist((items) => [...items, created]);
      setChecklistTitle("");
    } catch (value) {
      setMessage(value instanceof Error ? value.message : "Không thể thêm mục checklist");
    } finally {
      setAddingChecklist(false);
    }
  }

  async function toggleChecklistItem(item: TaskChecklistItem) {
    const snapshot = checklist;
    setChecklistBusy(item.id);
    setMessage("");
    setChecklist((items) => items.map((value) => (value.id === item.id ? { ...value, completed: !value.completed } : value)));
    try {
      const updated = await taskService.updateChecklistItem(workspaceId, task.id, item.id, { completed: !item.completed });
      setChecklist((items) => items.map((value) => (value.id === item.id ? updated : value)));
    } catch (value) {
      setChecklist(snapshot);
      setMessage(value instanceof Error ? value.message : "Không thể cập nhật checklist");
    } finally {
      setChecklistBusy("");
    }
  }

  async function removeChecklistItem(item: TaskChecklistItem) {
    setChecklistBusy(item.id);
    setMessage("");
    try {
      await taskService.deleteChecklistItem(workspaceId, task.id, item.id);
      setChecklist((items) => items.filter((value) => value.id !== item.id));
    } catch (value) {
      setMessage(value instanceof Error ? value.message : "Không thể xóa mục checklist");
    } finally {
      setChecklistBusy("");
    }
  }

  return (
    <div className="task-detail-live">
      <div className="board-sync">
        <ConnectionStatus state={connection} />
        {message && <span className="save-message">{message}</span>}
      </div>

      <form className="production-form ui-card task-edit-form" onSubmit={save}>
        <Field name="title" label="Tiêu đề" defaultValue={task.title} required />
        <label className="field">
          <span>Mô tả</span>
          <textarea name="description" defaultValue={task.description} />
        </label>
        <div className="form-grid">
          <label className="field">
            <span>Ưu tiên</span>
            <select name="priority" defaultValue={task.priority}>
              <option value="LOW">Thấp</option>
              <option value="MEDIUM">Trung bình</option>
              <option value="HIGH">Cao</option>
              <option value="URGENT">Khẩn cấp</option>
            </select>
          </label>
          <Field name="dueAt" label="Hạn hoàn thành" type="date" defaultValue={task.dueAt?.slice(0, 10)} />
        </div>
        <Button type="submit" disabled={saving || connection !== "connected"}>
          {saving ? "Đang lưu..." : "Lưu thay đổi"}
        </Button>
      </form>

      <section className="checklist-panel ui-card">
        <header>
          <CheckSquare size={18} />
          <h2>Checklist</h2>
          <Badge tone="gray">
            {completedChecklist}/{checklist.length}
          </Badge>
          <strong>{checklistProgress}%</strong>
        </header>
        <div
          className="checklist-progress"
          role="progressbar"
          aria-label="Tiến độ checklist"
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={checklistProgress}
        >
          <span style={{ width: `${checklistProgress}%` }} />
        </div>
        <div className="checklist-list">
          {checklist.length ? (
            checklist.map((item) => (
              <article className={item.completed ? "completed" : ""} key={item.id}>
                <input
                  type="checkbox"
                  aria-label={`Đánh dấu ${item.title}`}
                  checked={item.completed}
                  disabled={checklistBusy === item.id || connection !== "connected"}
                  onChange={() => void toggleChecklistItem(item)}
                />
                <span>{item.title}</span>
                <button
                  type="button"
                  aria-label={`Xóa mục ${item.title}`}
                  disabled={checklistBusy === item.id || connection !== "connected"}
                  onClick={() => void removeChecklistItem(item)}
                >
                  <Trash2 size={16} />
                </button>
              </article>
            ))
          ) : (
            <p className="column-empty">Chưa có mục checklist.</p>
          )}
        </div>
        <form className="checklist-form" onSubmit={addChecklistItem}>
          <label htmlFor="checklist-title">Thêm mục checklist</label>
          <div>
            <input
              id="checklist-title"
              value={checklistTitle}
              maxLength={240}
              onChange={(event) => setChecklistTitle(event.target.value)}
              placeholder="Ví dụ: Kiểm tra bản mobile"
            />
            <Button
              type="submit"
              disabled={
                addingChecklist || !checklistTitle.trim() || checklist.length >= 100 || connection !== "connected"
              }
            >
              <Plus size={16} />
              {addingChecklist ? "Đang thêm..." : "Thêm mục"}
            </Button>
          </div>
        </form>
      </section>

      <section className="attachments-panel ui-card">
        <header>
          <Paperclip size={18} />
          <h2>Tệp đính kèm</h2>
          <Badge tone="gray">{attachments.length}</Badge>
          <label className="attachment-upload">
            <Upload size={16} />
            <span>{uploading ? "Đang tải..." : "Thêm tệp"}</span>
            <input
              type="file"
              disabled={uploading || connection !== "connected"}
              accept="image/jpeg,image/png,image/webp,application/pdf,text/plain,text/csv,.docx,.xlsx"
              onChange={uploadAttachment}
            />
          </label>
        </header>
        <p className="attachment-help">Tối đa 10 MB · JPG, PNG, WebP, PDF, TXT, CSV, DOCX hoặc XLSX</p>
        <div className="attachment-list">
          {attachments.length ? (
            attachments.map((item) => (
              <article key={item.id}>
                <div>
                  <strong>{item.fileName}</strong>
                  <small>
                    {(item.size / 1024).toLocaleString("vi-VN", { maximumFractionDigits: 1 })} KB ·{" "}
                    {new Date(item.createdAt).toLocaleString("vi-VN")}
                  </small>
                </div>
                <button
                  type="button"
                  aria-label={`Tải ${item.fileName}`}
                  disabled={attachmentBusy === item.id}
                  onClick={() => void downloadAttachment(item)}
                >
                  <Download size={16} />
                </button>
                <button
                  type="button"
                  aria-label={`Xóa ${item.fileName}`}
                  disabled={attachmentBusy === item.id}
                  onClick={() => void removeAttachment(item)}
                >
                  <Trash2 size={16} />
                </button>
              </article>
            ))
          ) : (
            <p className="column-empty">Chưa có tệp đính kèm.</p>
          )}
        </div>
      </section>

      <section className="comments-panel ui-card">
        <header>
          <MessageCircle size={18} />
          <h2>Bình luận</h2>
          <Badge tone="gray">{comments.length}</Badge>
        </header>
        <div className="comment-list">
          {comments.length ? (
            comments.map((comment) => (
              <article className={comment.hidden || comment.deleted ? "muted" : ""} key={comment.id}>
                <strong>{comment.authorName}</strong>
                <p>{comment.body}</p>
                <small>{new Date(comment.createdAt).toLocaleString("vi-VN")}</small>
              </article>
            ))
          ) : (
            <p className="column-empty">Chưa có bình luận.</p>
          )}
        </div>
        <form className="comment-form" onSubmit={sendComment}>
          <label className="field">
            <span>Thêm bình luận</span>
            <textarea
              value={commentBody}
              onFocus={openSuggestions}
              onChange={(event) => setCommentBody(event.target.value)}
              placeholder="Viết bình luận; dùng @email để nhắc thành viên..."
            />
          </label>
          {suggestions.length > 0 && (
            <div className="mention-suggestions" role="listbox">
              {suggestions.map((member) => (
                <button type="button" key={member.id} onClick={() => chooseMention(member)}>
                  <strong>{member.name}</strong>
                  <small>@{member.email}</small>
                </button>
              ))}
            </div>
          )}
          <Button type="submit" disabled={commenting || !commentBody.trim() || connection !== "connected"}>
            {commenting ? "Đang gửi..." : "Gửi bình luận"}
          </Button>
        </form>
      </section>
    </div>
  );
}

/* eslint-disable jsx-a11y/click-events-have-key-events, jsx-a11y/no-static-element-interactions */
import { AlertCircle, Inbox } from "lucide-react";
import { Button } from "./button";

export function EmptyState({ title, body }: { title: string; body: string }) {
  return <div className="feedback-state"><Inbox /><h2>{title}</h2><p>{body}</p></div>;
}
export function ErrorState({ retry }: { retry?: () => void }) {
  return <div className="feedback-state error"><AlertCircle /><h2>Không tải được dữ liệu</h2><p>Vui lòng thử lại. Dữ liệu của bạn chưa bị thay đổi.</p>{retry && <Button onClick={retry}>Thử lại</Button>}</div>;
}
export function ListSkeleton({ rows = 3 }: { rows?: number }) {
  return <div className="skeleton-list" aria-label="Đang tải">{Array.from({ length: rows }, (_, index) => <span key={index} />)}</div>;
}

/* eslint-disable jsx-a11y/click-events-have-key-events, jsx-a11y/no-static-element-interactions */
"use client";

import * as Sentry from "@sentry/nextjs";
import { useEffect } from "react";

export default function GlobalError({ error, reset }: { error: Error & { digest?: string }; reset: () => void }) {
  useEffect(() => { Sentry.captureException(error); }, [error]);
  return <html lang="vi"><body><main className="auth-stage"><section className="auth-card"><h1>Không thể tải TaskFlow</h1><p>Lỗi đã được ghi nhận. Bạn có thể thử tải lại trang.</p><button className="button" onClick={reset}>Thử lại</button></section></main></body></html>;
}

/* eslint-disable jsx-a11y/click-events-have-key-events, jsx-a11y/no-static-element-interactions */
"use client";

import { useState, useEffect } from "react";
import { Wrench, RefreshCw, Clock } from "lucide-react";

export default function MaintenancePage() {
  const [timeLeft, setTimeLeft] = useState(1800); // 30 mins

  useEffect(() => {
    if (timeLeft > 0) {
      const timer = setTimeout(() => setTimeLeft(timeLeft - 1), 1000);
      return () => clearTimeout(timer);
    }
  }, [timeLeft]);

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m.toString().padStart(2, "0")}:${s.toString().padStart(2, "0")}`;
  };

  return (
    <div className="marketing min-h-screen flex items-center justify-center p-6 bg-[var(--surface)]">
      <div className="w-full max-w-md rounded-2xl border border-[var(--line)] bg-white p-8 shadow-xl text-center">
